#!/bin/sh
# Generated by tools/build-ipk.py from this template; edit the template, not output.
# First-party IPK is pinned here; official CLI is verified independently by setup.
set -eu
export PATH="/opt/bin:/opt/sbin:/usr/sbin:/usr/bin:/sbin:/bin:$PATH"
VERSION=0.3.1-alpha.14
IPK=asuswrt-merlin-trusttunnel_0.3.1-alpha.14-1_aarch64-3.10.ipk
IPK_SHA256=b1a8d5758bbc2923d7583fb9829b168dd382287c28f02b18321ebccc78b81740
[ "${1:-}" = --lab-only ] && [ "$#" -eq 1 ] || {
    echo 'Usage: install-online.sh --lab-only (experimental; installs disabled)' >&2; exit 2;
}
# Shared preflight only. No downloads, package changes or networking mutations.
tt_install_nvram() (
    # This path runs before runtime exists, including opkg preinst. Never hold
    # the controller lock in a firmware reader or accept partial timed-out data.
    exec 9>&-
    type timeout >/dev/null 2>&1 || { echo 'Install Entware coreutils-timeout before setup' >&2; return 1; }
    umask 077
    output=$(mktemp /tmp/ttm-install-nvram.XXXXXX) || return 1
    trap 'rm -f "$output"' EXIT
    trap 'exit 1' HUP INT TERM
    if timeout -k 1 2 nvram get "$1" >"$output" 2>/dev/null; then cat "$output"
    else echo 'Firmware settings read timed out or failed; installation cancelled' >&2; return 1; fi
)
tt_install_firmware_supported() {
    # Support floor, not a claim that every newer model/branch has been tested.
    case "$1" in 3.0.0.4|3.0.0.6) ;; *) return 1;; esac
    printf '%s\n' "$2" | awk -F. -v branch="$1" '
        NF==2 && $1~/^[0-9]+$/ && $2~/^[0-9]+$/ {
            ok=(branch=="3.0.0.6" ? $1>0 : ($1>388 || ($1==388 && $2>=12)))
        } END {exit !ok}'
}
tt_install_disabled() {
    for tt_install_path in /jffs/addons/trusttunnel /jffs/addons/trusttunnel/config /opt/trusttunnel /opt/trusttunnel/bin; do
        [ ! -L "$tt_install_path" ] || { echo 'Symlinked addon directory refused' >&2; return 1; }
    done
    for tt_install_state in enabled paused transaction client-update-journal.json; do
        [ ! -e "/jffs/addons/trusttunnel/config/$tt_install_state" ] &&
            [ ! -L "/jffs/addons/trusttunnel/config/$tt_install_state" ] || {
                echo 'Disable VPN and finish pending recovery before installation' >&2; return 1;
            }
    done
    [ ! -e /tmp/trusttunnel/resources-owned ] || {
        echo 'Existing VPN resources must be released with explicit disable first' >&2; return 1;
    }
}
tt_install_bootstrap_timeout() {
    # Called only by an explicit online/manual setup, never by opkg scripts.
    [ -z "${TT_ROOT:-}" ] || { echo 'Installation is prohibited with TT_ROOT' >&2; return 1; }
    type timeout >/dev/null 2>&1 && return 0
    [ "$(uname -s):$(uname -m)" = Linux:aarch64 ] &&
        [ "$(awk '/^Uid:/ {print $3}' /proc/self/status)" = 0 ] &&
        [ -f /usr/sbin/helper.sh ] && grep -Eq '^am_get_webui_page\(\)[[:space:]]*\{' /usr/sbin/helper.sh &&
        type opkg >/dev/null 2>&1 && [ -d /opt/etc/init.d ] || {
            echo 'Install coreutils-timeout in Entware before setup' >&2; return 1;
        }
    tt_install_disabled && opkg update && opkg install coreutils-timeout
}
tt_install_platform() {
    [ -z "${TT_ROOT:-}" ] || { echo 'Installation is prohibited with TT_ROOT' >&2; return 1; }
    [ "$(uname -s):$(uname -m)" = Linux:aarch64 ] || { echo 'Linux aarch64 router required' >&2; return 1; }
    # Firmware BusyBox can lack id until Entware dependencies are installed.
    [ "$(awk '/^Uid:/ {print $3}' /proc/self/status)" = 0 ] || { echo 'root required' >&2; return 1; }
    type nvram >/dev/null 2>&1 && tt_install_nvram rc_support | grep -qw am_addons || {
        echo 'Merlin Addons API required' >&2; return 1;
    }
    tt_install_firmware_supported "$(tt_install_nvram firmver)" "$(tt_install_nvram buildno)" || {
        echo 'Minimum supported Merlin firmware: 3004.388.12 (older versions untested)' >&2; return 1;
    }
    [ "$(tt_install_nvram jffs2_scripts)" = 1 ] || { echo 'Enable JFFS custom scripts in Merlin first' >&2; return 1; }
    type opkg >/dev/null 2>&1 && [ -d /opt/etc/init.d ] || { echo 'Working Entware is required' >&2; return 1; }
    # opkg already checked the package architecture in maintainer context.
    # Never run another opkg process from inside its scripts/package lock.
    if [ "${1:-}" != --from-ipk ]; then
        opkg print-architecture | awk '$1=="arch" && $2=="aarch64-3.10" {ok=1} END {exit !ok}' || {
            echo 'Entware aarch64-3.10 required' >&2; return 1;
        }
    fi
    tt_install_disabled
}
tt_install_existing_client() {
    # 0: verified owned client to preserve; 1: absent; 2: unknown/corrupt, refuse.
    tt_install_bin=/opt/trusttunnel/bin/trusttunnel_client
    if [ ! -e "$tt_install_bin" ] && [ ! -L "$tt_install_bin" ] && [ ! -e "$tt_install_bin.sha256" ] && [ ! -L "$tt_install_bin.sha256" ]; then return 1; fi
    [ -f "$tt_install_bin" ] && [ ! -L "$tt_install_bin" ] &&
        [ -f "$tt_install_bin.sha256" ] && [ ! -L "$tt_install_bin.sha256" ] || return 2
    tt_install_hash=$(cat "$tt_install_bin.sha256")
    printf '%s' "$tt_install_hash" | grep -Eq '^[a-f0-9]{64}$' &&
        [ "$(sha256sum "$tt_install_bin" | awk '{print $1}')" = "$tt_install_hash" ] || return 2
    # Also allow recovery of a first installation interrupted after the pinned
    # initial CLI was installed, before the addon ownership marker was written.
    [ "$tt_install_hash" = 0eceaaf0c7afd07b10dd66262c7812ec52aa0ed631d65373f58f4b8318fb5869 ] || {
        [ -f /jffs/addons/trusttunnel/.trusttunnel-owned ] && [ ! -L /jffs/addons/trusttunnel/.trusttunnel-owned ] &&
            [ "$(cat /jffs/addons/trusttunnel/.trusttunnel-owned)" = trusttunnel-merlin-addon-v1 ] || return 2
    }
}
tt_install_bootstrap_timeout
tt_install_platform ''
# Only bootstrap verification tools when missing; dependencies use configured Entware feeds.
if ! type sha256sum >/dev/null 2>&1 || ! type curl >/dev/null 2>&1 || ! type tar >/dev/null 2>&1; then
    opkg update
    opkg install coreutils-sha256sum curl ca-bundle tar
fi
umask 077
WORK="/opt/ttm-setup-online-$(date +%Y%m%d-%H%M%S)-$$"
mkdir -m 700 "$WORK"
printf '%s\n' trusttunnel-merlin-staging-v1 >"$WORK/.trusttunnel-owned"
printf 'Installing asuswrt-merlin-trusttunnel %s\n' "$VERSION"
curl --fail --location --proto '=https' --proto-redir '=https' --connect-timeout 20 --max-time 180 \
    "https://github.com/VitaliyYakob/asuswrt-merlin-trusttunnel/releases/download/v${VERSION}/${IPK}" -o "$WORK/$IPK"
[ "$(sha256sum "$WORK/$IPK" | awk '{print $1}')" = "$IPK_SHA256" ] || {
    echo 'IPK SHA-256 mismatch; package was not extracted or installed' >&2; exit 1;
}
# Extract ONLY the dependency helper from the now verified package; no remote eval.
tar -xOzf "$WORK/$IPK" ./data.tar.gz >"$WORK/data.tar.gz"
for helper in prepare-entware.sh router-platform.sh; do
    tar -xOzf "$WORK/data.tar.gz" "./opt/share/asuswrt-merlin-trusttunnel/tools/$helper" >"$WORK/$helper"
done
sh "$WORK/prepare-entware.sh" --lab-only
opkg install "$WORK/$IPK"
rm -f "$WORK/$IPK" "$WORK/data.tar.gz" "$WORK/prepare-entware.sh" "$WORK/router-platform.sh" "$WORK/.trusttunnel-owned"
rmdir "$WORK"
printf '%s\n' 'Installed with VPN disabled. Open VPN > TrustTunnel over HTTPS.'
